function diagramBlockRoot(e){return e.closest("div.highlight")||e.parentNode}document.addEventListener("DOMContentLoaded",function(){if(typeof echarts=="undefined")return;document.querySelectorAll("pre code.language-echarts, pre code.echarts").forEach(e=>{try{const s=diagramBlockRoot(e),n=JSON.parse(e.textContent),o=n.height||"500px";delete n.height;const t=document.createElement("div");t.className="echarts-container echarts-loading",t.style.height=o,t.innerHTML='<div><span class="spinner">⚙️</span> Rendering chart...</div>',s.parentNode.replaceChild(t,s),setTimeout(()=>{t.className="echarts-container",t.innerHTML="";const e=echarts.init(t);e.setOption(n),window.addEventListener("resize",()=>e.resize())},400)}catch(n){console.error("ECharts code block error:",n);const t=document.createElement("div");t.className="chart-error",t.textContent="Error rendering ECharts diagram: "+n.message;const s=diagramBlockRoot(e);s.parentNode.insertBefore(t,s)}}),document.querySelectorAll(".echarts-container[data-chart]").forEach(e=>{try{const t=echarts.init(e);t.setOption(JSON.parse(e.dataset.chart)),window.addEventListener("resize",()=>t.resize())}catch(e){console.error("ECharts config error:",e)}})})